<style>.ntw-page{width:min(900px,calc(100% - 32px));margin:0 auto 70px}.tool-head{text-align:center;padding:48px 0 24px}.eyebrow{color:#5b43ff;font-size:10px;font-weight:900;letter-spacing:1.8px}.tool-head h1{margin:14px 0 8px;font-size:clamp(38px,6vw,56px);line-height:1;letter-spacing:-2.5px}.tool-head p{margin:0 auto;color:#667085;font-size:15px}.ntw-card{padding:24px;background:#fff;border:1px solid #e7eaf0;border-radius:24px;box-shadow:0 18px 50px rgba(16,24,40,.07)}.controls{display:grid;grid-template-columns:.8fr 1.5fr;gap:12px}.controls label{display:grid;gap:7px;color:#344054;font-size:11px;font-weight:800}.controls input,.controls select{height:46px;box-sizing:border-box;padding:0 12px;border:1px solid #dfe3eb;border-radius:11px;background:#fcfdff;color:#172033;font-size:13px;outline:0}.actions{display:flex;gap:9px;margin:14px 0}.actions button,.result button{padding:10px 16px;border:1px solid #dfe3eb;border-radius:10px;background:#fff;color:#344054;font-size:10px;font-weight:900;cursor:pointer}.actions .primary{border:0;background:linear-gradient(90deg,#5d46ff,#3e7dff);color:#fff}.result{padding:18px;border:1px solid #e7eaf0;border-radius:15px;background:#fafbff}.result>span{color:#69738e;font-size:10px;font-weight:800}.result p{margin:10px 0 15px;color:#263052;font:18px/1.6 Georgia,serif;word-break:break-word}.result button{background:#111936;color:#fff;border-color:#111936}.info-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:18px}.info-grid article{padding:22px;border:1px solid #e7eaf0;border-radius:18px;background:#fff}.info-grid h2{margin:0 0 10px;font-size:17px}.info-grid p{margin:0;color:#667085;font-size:12px;line-height:1.75}@media(max-width:650px){.ntw-page{width:calc(100% - 20px)}.ntw-card{padding:16px}.controls{grid-template-columns:1fr}.actions{flex-wrap:wrap}.actions button{flex:1}.info-grid{grid-template-columns:1fr}}
</style><script>(()=>{const ones=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine'],teens=['Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'],tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];function under1000(n){let s='';if(n>=100){s+=ones[Math.floor(n/100)]+' Hundred';n%=100;if(n)s+=' '}if(n>=20){s+=tens[Math.floor(n/10)];if(n%10)s+=' '+ones[n%10]}else if(n>=10)s+=teens[n-10];else if(n)s+=ones[n];return s}function indian(n){if(n===0)return'Zero';let parts=[];const crore=Math.floor(n/10000000);n%=10000000;if(crore)parts.push(indian(crore)+' Crore');const lakh=Math.floor(n/100000);n%=100000;if(lakh)parts.push(under1000(lakh)+' Lakh');const thousand=Math.floor(n/1000);n%=1000;if(thousand)parts.push(under1000(thousand)+' Thousand');if(n)parts.push(under1000(n));return parts.join(' ')}function international(n){if(n===0)return'Zero';const scales=['','Thousand','Million','Billion','Trillion','Quadrillion'];let i=0,parts=[];while(n>0){const chunk=n%1000;if(chunk)parts.unshift(under1000(chunk)+(scales[i]?' '+scales[i]:''));n=Math.floor(n/1000);i++}return parts.join(' ')}const input=document.getElementById('number'),system=document.getElementById('system'),output=document.getElementById('output');document.getElementById('convert').onclick=()=>{const raw=input.value.replace(/,/g,'').trim();if(!/^\d+$/.test(raw)){output.textContent='Please enter a valid whole number.';return}const n=Number(raw);if(!Number.isSafeInteger(n)){output.textContent='Please enter a smaller number.';return}output.textContent=system.value==='indian'?indian(n):international(n)};document.getElementById('clear').onclick=()=>{input.value='';output.textContent='Your number in words will appear here.'};document.getElementById('copy').onclick=async()=>{if(!output.textContent||output.textContent.includes('will appear'))return;await navigator.clipboard.writeText(output.textContent);document.getElementById('copy').textContent='Copied';setTimeout(()=>document.getElementById('copy').textContent='Copy Result',1000)};input.addEventListener('keydown',e=>{if(e.key==='Enter')document.getElementById('convert').click()})})();</script>
